62	const BASE_PREMIUMS: Record<string, number> = {
63	  sword: 100,
64	  amulet: 60,
65	  staff: 80,
66	  potion: 40,
67	  rune: 25,
68	  moonstone: 25,
69	};
70	
71	const INSURANCE_VALUES: Record<string, number> = {
72	  sword: 1000,
73	  amulet: 600,
74	  staff: 800,
75	  potion: 400,
76	  rune: 250,
77	  moonstone: 250,
78	};
79	
80	const PROCESSING_FEE = 5;
81	
82	const WHOLE_PERCENT = 100;
83	
84	/**
85	 * Adjusts an amount by a percentage. A positive percent is a surcharge, a
86	 * negative one a discount.
87	 *
88	 * Multiplying before dividing keeps the arithmetic exact. A 1.1 multiplier
89	 * would not: floating-point `100 * 1.1` is 110.00000000000001, which rounds
90	 * up to 111 and yields a 116 G premium instead of 115 G.
91	 */
92	const adjustByPercent = (amount: number, percent: number): number =>
93	  (amount * (WHOLE_PERCENT + percent)) / WHOLE_PERCENT;
94	
95	/** All rounding is in the MHPCO's favor — always up. */
96	const roundInMHPCOsFavor = Math.ceil;
97	
98	const BUILDING_BLOCK_SIZE = 3;
99	const BUILDING_BLOCK_PREMIUM = 60;
100	
101	/** Item kinds are compared by type — both grouping and claims match on it. */
102	const isOfType =
103	  (type: string) =>
104	  (item: InsuredItem): boolean =>
105	    item.type === type;
106	
107	/** Only items of one and the same kind group into a block. */
108	const areAllTheSameKind = ([first, ...rest]: InsuredItem[]): boolean =>
109	  first !== undefined && rest.every(isOfType(first.type));
110	
111	/**
112	 * How many flat-rate blocks this list forms. A mixed list forms none — only
113	 * alike items group — and so does any list too short to fill one block.
114	 */
115	const countCompleteBlocks = (items: InsuredItem[]): number =>
116	  areAllTheSameKind(items) ? Math.floor(items.length / BUILDING_BLOCK_SIZE) : 0;
117	
118	const CURSED_SURCHARGE_PERCENT = 50;
119	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
120	
121	/**
122	 * Enchantment drives two unrelated rules at two different levels, so each
123	 * threshold is named for the rule it belongs to rather than for the adjective
124	 * the spec happens to use. Level 5 makes an item dearer to insure; level 8
125	 * makes damage to it cheaper to reimburse. Neither level should ever be
126	 * substituted for the other.
127	 */
128	const SURCHARGEABLE_ENCHANTMENT_LEVEL = 5;
129	
130	/** A risk rule contributes its percent only when the item trips it. */
131	const percentWhen = (applies: boolean, percent: number): number =>
132	  applies ? percent : 0;
133	
134	const enchantmentOf = (item: InsuredItem): number => item.enchantment ?? 0;
135	
136	const attractsEnchantmentSurcharge = (item: InsuredItem): boolean =>
137	  enchantmentOf(item) >= SURCHARGEABLE_ENCHANTMENT_LEVEL;
138	
139	/** Risk surcharges add to the base premium; they do not compound. */
140	const riskSurchargePercentFor = (item: InsuredItem): number =>
141	  percentWhen(item.cursed === true, CURSED_SURCHARGE_PERCENT) +
142	  percentWhen(
143	    attractsEnchantmentSurcharge(item),
144	    HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
145	  );
146	
147	/** An item's list price with its own risk surcharges applied. */
148	const riskAdjustedPremiumFor = (item: InsuredItem): number =>
149	  adjustByPercent(BASE_PREMIUMS[item.type], riskSurchargePercentFor(item));
150	
151	/**
152	 * Prices an item list: alike items are grouped into building blocks sold at a
153	 * flat rate, and whatever is left over is priced item by item, each at its own
154	 * risk-adjusted premium.
155	 */
156	const priceItems = (items: InsuredItem[]): number => {
157	  const blocks = countCompleteBlocks(items);
158	  const leftovers = items.slice(blocks * BUILDING_BLOCK_SIZE);
159	
160	  return (
161	    blocks * BUILDING_BLOCK_PREMIUM +
162	    leftovers.reduce((sum, item) => sum + riskAdjustedPremiumFor(item), 0)
163	  );
164	};
165	
166	/** Discounts are negative adjustments — long-standing customers pay 20% less. */
167	const LOYALTY_DISCOUNT_PERCENT = -20;
168	const LOYALTY_YEARS = 2;
169	const REPEAT_CONTRACT_DISCOUNT_PERCENT = -15;
170	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
171	
172	const isLongStanding = (customer: Customer): boolean =>
173	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
174	
175	/** The first contract is assessed; every later one earns a discount instead. */
176	const contractPercentFor = (isFirstContract: boolean): number =>
177	  isFirstContract
178	    ? FIRST_INSURANCE_SURCHARGE_PERCENT
179	    : REPEAT_CONTRACT_DISCOUNT_PERCENT;
180	
181	/**
182	 * The customer's own standing modifies the item price. Unlike the risk
183	 * surcharges, which add up before being applied once, these modifiers
184	 * COMPOUND: each applies to the result of the last. A 20% discount followed
185	 * by a 10% surcharge is 100 -> 80 -> 88, not 100 -> 90.
186	 */
187	const applyCustomerModifiers = (
188	  price: number,
189	  customer: Customer,
190	  isFirstContract: boolean,
191	): number => {
192	  const afterLoyalty = adjustByPercent(
193	    price,
194	    percentWhen(isLongStanding(customer), LOYALTY_DISCOUNT_PERCENT),
195	  );
196	
197	  return adjustByPercent(afterLoyalty, contractPercentFor(isFirstContract));
198	};
199	
200	/**
201	 * The premium pipeline, in the order the spec states it: price the items,
202	 * apply the customer's modifiers, round, then add the processing fee last.
203	 */
204	const quotePremium = (
205	  items: InsuredItem[],
206	  customer: Customer,
207	  isFirstContract: boolean,
208	): QuoteResult => ({
209	  premium:
210	    roundInMHPCOsFavor(
211	      applyCustomerModifiers(priceItems(items), customer, isFirstContract),
212	    ) + PROCESSING_FEE,
213	});
214	
215	/**
216	 * Contracts are counted by quote step, not by step position — a scenario may
217	 * open with a claim, and the quote that follows is still the customer's first
218	 * contract.
219	 */
220	const FIRST_CONTRACT = 1;
221	
222	/**
223	 * Which quote steps open the customer's first contract, keyed by step index.
224	 *
225	 * Contract order is a property of the steps alone: it depends on how many
226	 * quotes precede a step, never on what any claim did. So it is settled once,
227	 * before the traversal, rather than tracked as running state alongside the cap
228	 * ledger — which does depend on the order claims are settled in.
229	 */
230	const firstContractSteps = (steps: Step[]): ReadonlySet<number> => {
231	  const quoteIndices = steps.flatMap((step, index) =>
232	    step.op === "quote" ? [index] : [],
233	  );
234	
235	  return new Set(quoteIndices.slice(0, FIRST_CONTRACT));
236	};
237	
238	const DEDUCTIBLE = 100;
239	const CAP_MULTIPLE = 2;
240	
241	const insuranceSumOf = (items: InsuredItem[]): number =>
242	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
243	
244	/**
245	 * Stands in for a damage whose item type the policy does not list. Its bare
246	 * attributes trip no rate rule, so such a damage reimburses in full.
247	 */
248	const UNCOVERED_ITEM: InsuredItem = { type: "" };
249	
250	/** See SURCHARGEABLE_ENCHANTMENT_LEVEL — a different rule at a different level. */
251	const HALVING_ENCHANTMENT_LEVEL = 8;
252	const HALF = 0.5;
253	const IN_FULL = 1;
254	
255	const DRAGON_MATERIAL = "dragon";
256	
257	const isDragonMade = (item: InsuredItem): boolean =>
258	  item.material === DRAGON_MATERIAL;
259	
260	/** The mirror of attractsEnchantmentSurcharge, at the halving rule's level. */
261	const attractsEnchantmentHalving = (item: InsuredItem): boolean =>
262	  enchantmentOf(item) >= HALVING_ENCHANTMENT_LEVEL;
263	
264	/**
265	 * Damage to an item enchanted this far is only half reimbursed — unless it is
266	 * dragon-made, which the MHPCO always makes good in full whatever else is true
267	 * of the item. Dragon material is checked first because it overrides halving,
268	 * not the other way round.
269	 */
270	const reimbursementRateFor = (item: InsuredItem): number =>
271	  attractsEnchantmentHalving(item) && !isDragonMade(item) ? HALF : IN_FULL;
272	
273	/**
274	 * The damaged item's entry in the policy. A damage naming something the policy
275	 * does not cover reimburses in full — no rate rule can trip without an item to
276	 * read it from.
277	 */
278	const damagedItemIn = (
279	  damage: Damage,
280	  insuredItems: InsuredItem[],
281	): InsuredItem => insuredItems.find(isOfType(damage.itemType)) ?? UNCOVERED_ITEM;
282	
283	const reimbursableAmountOf = (
284	  damage: Damage,
285	  insuredItems: InsuredItem[],
286	): number =>
287	  damage.amount * reimbursementRateFor(damagedItemIn(damage, insuredItems));
288	
289	/** One incident is one deductible, so the damages are totalled before it applies. */
290	const totalDamageOf = (
291	  incident: Incident,
292	  insuredItems: InsuredItem[],
293	): number =>
294	  incident.damages.reduce(
295	    (sum, damage) => sum + reimbursableAmountOf(damage, insuredItems),
296	    0,
297	  );
298	
299	/** The MHPCO never owes a negative amount; below the deductible it owes nothing. */
300	const OWES_NOTHING = 0;
301	
302	/**
303	 * What the incident itself puts the MHPCO on the hook for. The customer bears
304	 * the deductible, so only the damage above it is owed — and an incident that
305	 * stays within the deductible is owed nothing rather than turning the shortfall
306	 * into a debt.
307	 *
308	 * This is the incident's own figure, taking no account of the policy it is
309	 * claimed against. What the policy can actually pay out is a separate question,
310	 * answered by `limitedByRemainingCover`.
311	 */
312	const amountOwedFor = (
313	  incident: Incident,
314	  insuredItems: InsuredItem[],
315	): number =>
316	  Math.max(OWES_NOTHING, totalDamageOf(incident, insuredItems) - DEDUCTIBLE);
317	
318	/**
319	 * What the policy can still pay, whatever the incident owes. Cover is a finite
320	 * pot shared by every claim on the policy, so a claim is paid only as far as
321	 * the pot reaches.
322	 *
323	 * The counterpart of the deductible floor in `amountOwedFor`: that one bounds
324	 * the incident from below, this one bounds the policy from above. Two separate
325	 * rules, so two separate names.
326	 */
327	const limitedByRemainingCover = (
328	  amountOwed: number,
329	  remainingCover: number,
330	): number => Math.min(amountOwed, remainingCover);
331	
332	const settleClaim = (
333	  incident: Incident,
334	  insuredItems: InsuredItem[],
335	  capBefore: number,
336	): ClaimResult => {
337	  const payout = limitedByRemainingCover(
338	    amountOwedFor(incident, insuredItems),
339	    capBefore,
340	  );
341	
342	  return { payout, remainingCap: capBefore - payout };
343	};
344	
345	/** A policy's total cover: twice the insurance sum, shared by all its claims. */
346	const capOf = (insuredItems: InsuredItem[]): number =>
347	  CAP_MULTIPLE * insuranceSumOf(insuredItems);
348	
349	/**
350	 * A claim names the quote step it is made against; the items on that step are
351	 * the ones the policy covers.
352	 */
353	const itemsCoveredBy = (claim: ClaimStep, steps: Step[]): InsuredItem[] => {
354	  const policy = steps[claim.policy];
355	
356	  return policy.op === "quote" ? policy.items : [];
357	};
358	
359	/**
360	 * The running cover left on each policy, keyed by the quote step that opened
361	 * it. A policy absent from the ledger has not been claimed against yet, so its
362	 * remaining cover is still the full cap.
363	 */
364	type CapLedger = Map<number, number>;
365	
366	/**
367	 * Settles one claim against the ledger and draws the payout down from the
368	 * policy's remaining cover. This is the one step kind whose result depends on
369	 * the steps before it, so it is also the only one that writes to the ledger.
370	 */
371	const settleClaimAgainstLedger = (
372	  claim: ClaimStep,
373	  steps: Step[],
374	  remainingCaps: CapLedger,
375	): ClaimResult => {
376	  const insuredItems = itemsCoveredBy(claim, steps);
377	  const capBefore = remainingCaps.get(claim.policy) ?? capOf(insuredItems);
378	  const result = settleClaim(claim.incident, insuredItems, capBefore);
379	
380	  remainingCaps.set(claim.policy, result.remainingCap);
381	
382	  return result;
383	};
384	
385	/**
386	 * Works the scenario's steps in order, returning one result per step.
387	 *
388	 * The traversal is a `for...of` rather than a `map` because it is genuinely
389	 * order-dependent: each claim draws down a cap that later claims on the same
390	 * policy read back. `map` would compute the same answers — it runs
391	 * left-to-right — but it advertises an independent per-element transform, and
392	 * this is not one. The loop states the sequencing the cap ledger relies on.
393	 */
394	export const runScenario = ({
395	  customer,
396	  steps,
397	}: Scenario): ScenarioResults => {
398	  const remainingCaps: CapLedger = new Map();
399	  const isFirstContract = firstContractSteps(steps);
400	  const results: StepResult[] = [];
401	
402	  for (const [index, step] of steps.entries()) {
403	    results.push(
404	      step.op === "quote"
405	        ? quotePremium(step.items, customer, isFirstContract.has(index))
406	        : settleClaimAgainstLedger(step, steps, remainingCaps),
407	    );
408	  }
409	
410	  return { results };
411	};
