2	import { pathToFileURL } from "node:url";
3	import { runScenario, type Scenario } from "./claim-office.js";
4	
5	/** The whole CLI, as a function: JSON scenario in, JSON results out. */
6	export const runCli = (input: string): string =>
7	  JSON.stringify(runScenario(JSON.parse(input) as Scenario));
8	
9	const readAll = async (stream: NodeJS.ReadableStream): Promise<string> => {
10	  const chunks: string[] = [];
11	
12	  stream.setEncoding("utf8");
13	  for await (const chunk of stream) chunks.push(chunk as string);
14	
15	  return chunks.join("");
16	};
17	
18	/**
19	 * Whether this module is the program node was asked to run, rather than one
20	 * imported by something else.
21	 *
22	 * ESM has no `require.main === module`, but it does expose the two halves of
23	 * the question exactly: `import.meta.url` is this file, and `process.argv[1]`
24	 * is the entry script. Comparing them asks what we mean. Matching the filename
25	 * against "cli.ts" only approximates it, and silently stops matching the day
26	 * the file is compiled to cli.js or renamed.
27	 */
28	const isEntryPoint = (): boolean =>
29	  process.argv[1] !== undefined &&
30	  import.meta.url === pathToFileURL(process.argv[1]).href;
31	
32	/** Importing this module from a test must not consume the runner's stdin. */
33	if (isEntryPoint()) {
34	  process.stdout.write(runCli(await readAll(process.stdin)));
35	}
